use std::error::Error;
use std::fs;
use std::path::Path;

pub fn run() -> Result<(), Box<dyn Error>> {
    // read the file "template.html"  [read_file/to_string + propagate]
    let contents = fs::read_to_string("template.html")?;
    // create the directory "out" if missing  [create_dir/create_dir_all + propagate]
    fs::create_dir_all("out")?;
    // atomically write it to "out/index.html"  [write_file/atomic + propagate]
    let tmp = Path::new("out/index.html").with_extension("tmp");
    fs::write(&tmp, &contents).and_then(|()| fs::rename(&tmp, "out/index.html"))?;
    Ok(())
}
